insert into public.vouchers
  (code, title, description, discount_type, discount_value, min_purchase, max_discount, expires_at, is_active)
values
  ('WELCOME20', 'Welcome Voucher', 'New to BookVerse? Take 20% off your first order, up to ₱300 off.', 'percent', 20, 500, 300, now() + interval '60 days', true),
  ('FREESHIP', 'Free Shipping Voucher', 'Flat ₱60 off shipping on any order over ₱800.', 'fixed', 60, 800, null, now() + interval '30 days', true),
  ('MANGA100', '₱100 Off Manga & Manhwa', 'Get ₱100 off when you spend ₱1,000 or more storewide.', 'fixed', 100, 1000, null, now() + interval '45 days', true),
  ('BOOKWORM10', 'Bookworm 10% Off', '10% off your entire order, no minimum spend.', 'percent', 10, 0, 200, now() + interval '90 days', true)
on conflict (code) do nothing;
